export function brickHit(ball, bricks) {
  const r = ball.r;
  const x0 = (ball.px !== undefined) ? ball.px : ball.x;
  const y0 = (ball.py !== undefined) ? ball.py : ball.y;
  const x1 = ball.x;
  const y1 = ball.y;
  const dx = x1 - x0;
  const dy = y1 - y0;
  const dist = Math.hypot(dx, dy);
  const steps = Math.max(1, Math.ceil(dist / 5)); // substep ~5px, safe for brick thickness & ball diameter

  const destroyed = [];
  let bounced = false;

  for (let i = 0; i <= steps; i++) {
    const cx = x0 + dx * (i / steps);
    const cy = y0 + dy * (i / steps);
